LANGUAGE sql;

select p.id, p.amount, s.nearest from t as p
left join lateral
(
select p.id, array_agg(l.id) as nearest from (
select id from t where amount < p.amount
order by amount <-> p.amount limit 10
) l
) s
using(id)
where p.id <= 500;

